# Step 1-2: Define the Person class
class Person:
    def __init__(self, name):
        self.name = name

    def greet(self):
        print(f"Hello, my name is {self.name}.")

# Step 3-4: Define the Student class inheriting from Person
class Student(Person):
    def study(self):
        print(f"{self.name} is studying hard.")

# Step 5: Create student1 instance
student1 = Student('Alex')

# Step 6: Call both methods
student1.greet()
student1.study()

